import { Link, useLocation } from "react-router-dom";
import { Moon, Sun } from "lucide-react";
import { useTheme } from "../../hooks";
import { useLanguage } from "../../contexts/LanguageContext";
import "./Header.css";

export function Header() {
  const location = useLocation();
  const { theme, toggleTheme } = useTheme();
  const { language, t, setLanguage } = useLanguage();

  const toggleLanguage = () => {
    setLanguage(language === "en" ? "pt-BR" : "en");
  };

  return (
    <header className="header">
      <div className="header-container">
        <Link to="/" className="header-logo">
          <img src="/assets/padlock-crop.png" alt="Logo" className="logo-image" />
        </Link>
        <div className="header-actions">
          <nav className="header-nav">
            <Link
              to="/"
              className={`nav-link ${location.pathname === "/" ? "active" : ""}`}
            >
              {t.common.home}
            </Link>
            <Link
              to="/dashboard"
              className={`nav-link ${
                location.pathname === "/dashboard" ? "active" : ""
              }`}
            >
              {t.common.dashboard}
            </Link>
            <Link
              to="/about"
              className={`nav-link ${
                location.pathname === "/about" ? "active" : ""
              }`}
            >
              {t.common.about}
            </Link>
          </nav>
          <div className="header-controls">
            <button
              className="lang-toggle"
              onClick={toggleLanguage}
              aria-label={t.aria.toggleLanguage(language === "en" ? "pt-BR" : "en")}
              type="button"
            >
              <span className="lang-code">{language === "en" ? "EN" : "PT"}</span>
            </button>
            <button
              className="theme-toggle"
              onClick={toggleTheme}
              aria-label={t.aria.toggleTheme(theme === "light" ? "dark" : "light")}
              type="button"
            >
              <span className="theme-icon" aria-hidden="true">
                {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
              </span>
            </button>
          </div>
        </div>
      </div>
    </header>
  );
}
