const getEmail = (): string => {
  const codes = [104, 111, 110, 100, 97, 46, 100, 97, 116, 97, 46, 115, 99, 105, 101, 110, 99, 101, 64, 103, 109, 97, 105, 108, 46, 99, 111, 109];
  return String.fromCharCode(...codes);
};

/**
 * Get mailto link with obfuscated email
 * @param serviceName - Service name to include in subject
 * @param buttonText - Optional button text for subject
 * @param body - Optional email body
 */
export const getMailtoLink = (serviceName?: string, buttonText?: string, body?: string): string => {
  const email = getEmail();
  let mailto = `mailto:${email}`;
  const params: string[] = [];
  
  // Build subject with service name
  if (serviceName) {
    const subject = buttonText 
      ? `${buttonText} - ${serviceName}`
      : `Contact - ${serviceName}`;
    params.push(`subject=${encodeURIComponent(subject)}`);
  } else if (buttonText) {
    params.push(`subject=${encodeURIComponent(buttonText)}`);
  }
  
  if (body) {
    params.push(`body=${encodeURIComponent(body)}`);
  }
  
  if (params.length > 0) {
    mailto += `?${params.join('&')}`;
  }
  
  return mailto;
};

/**
 * Handle email click - opens mailto link in a new tab
 * @param serviceName - Service name to include in subject
 * @param buttonText - Optional button text for subject
 * @param body - Optional email body
 */
export const handleEmailClick = (serviceName?: string, buttonText?: string, body?: string): void => {
  const mailtoLink = getMailtoLink(serviceName, buttonText, body);
  window.open(mailtoLink, '_blank');
};

